// ---------------------------------------------------------------
// PRISMA · registro compartido de audio
// Lo crea la primera pista que se ejecute; las otras dos lo reutilizan.
// El index.html controla la experiencia a traves de window.PRISMA_AUDIO
// ---------------------------------------------------------------
if (!window.PRISMA_AUDIO) {
	window.PRISMA_AUDIO = {

		pistas: new Map(),
		actual: null,
		oyentes: [],

		registrar: function (pista) {
			this.pistas.set(pista.id, pista);
			this.avisar();
		},

		// El index se suscribe aqui para pintar el estado de los botones
		alCambiar: function (fn) {
			this.oyentes.push(fn);
			fn(this.actual, this.listar());
		},

		avisar: function () {
			for (const fn of this.oyentes) fn(this.actual, this.listar());
		},

		listar: function () {
			return Array.from(this.pistas.keys());
		},

		reproducir: function (id) {
			const pista = this.pistas.get(id);
			if (!pista || !pista.asset) return;
			this.detener();
			pista.asset.play();
			this.actual = id;
			this.avisar();
		},

		// Tocar la pista que ya suena la apaga
		alternar: function (id) {
			if (this.actual === id) this.detener();
			else this.reproducir(id);
		},

		detener: function () {
			for (const pista of this.pistas.values()) {
				if (pista.asset) pista.asset.stop();
			}
			this.actual = null;
			this.avisar();
		},

		// La llama el evento 'ended' cuando una pista sin loop se acaba sola
		terminada: function (id) {
			if (this.actual !== id) return;
			this.actual = null;
			this.avisar();
		}
	};
}

// ---------------------------------------------------------------
// PISTA: MAGENTA   ·   objeto: Botella
// Para usar tu propio sonido cambia `url` por una ruta local,
// por ejemplo 'assets/audio/magenta.mp3'
// ---------------------------------------------------------------
const PISTA = {
	id: 'magenta',
	nombre: 'MAGENTA',
	url: 'https://paralax-mu.vercel.app/assets/sonido%20burbuja%202.mp3',
	loop: false,          // true = suena en bucle hasta que la apaguen
	volumen: 1
};

PISTA.asset = player.loadAudio(PISTA.id, PISTA.url, (audio) => {
	audio.setLoop(PISTA.loop);
	audio.setVolume(PISTA.volumen);
});

// Cuando una pista sin loop llega al final, se libera el estado
PISTA.asset.audio.addEventListener('ended', function () {
	window.PRISMA_AUDIO.terminada(PISTA.id);
});

window.PRISMA_AUDIO.registrar(PISTA);

// Tocar el objeto dentro de la escena dispara la misma pista que el boton
this.onClick = function () {
	window.PRISMA_AUDIO.alternar(PISTA.id);
};

